mod common;

use axum::http::{Method, StatusCode};
use axum_bookclub::app;
use common::send;
use serde_json::json;

async fn make_club(router: &axum::Router, max_members: Option<u32>) -> u64 {
    let (_, body) = send(
        router,
        Method::POST,
        "/api/clubs",
        Some(json!({"name": "C", "description": "x", "max_members": max_members})),
    )
    .await;
    body["id"].as_u64().unwrap()
}

#[tokio::test]
async fn bulk_add_rejects_whole_batch_when_cumulative_exceeds_capacity() {
    let router = app();
    let club_id = make_club(&router, Some(2)).await;

    let (status, _) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{club_id}/members/bulk-add"),
        Some(json!({"members": [
            {"name": "A", "email": "a@example.com"},
            {"name": "B", "email": "b@example.com"},
            {"name": "C", "email": "c@example.com"}
        ]})),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST);

    let (_, listed) = send(&router, Method::GET, &format!("/api/clubs/{club_id}/members"), None).await;
    assert_eq!(listed.as_array().unwrap().len(), 0);
}

#[tokio::test]
async fn bulk_add_succeeds_within_capacity() {
    let router = app();
    let club_id = make_club(&router, Some(3)).await;

    let (status, _) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{club_id}/members/bulk-add"),
        Some(json!({"members": [
            {"name": "A", "email": "a@example.com"},
            {"name": "B", "email": "b@example.com"}
        ]})),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED);
}

