use std::sync::Arc;

use axum::extract::{Path, State};
use axum::http::StatusCode;
use axum::response::IntoResponse;
use axum::Json;
use serde::Deserialize;
use serde_json::json;

use crate::state::{AppState, Member};

#[derive(Deserialize)]
pub struct CreateMember {
    pub name: Option<String>,
    pub email: Option<String>,
}

pub async fn create_member(
    State(state): State<Arc<AppState>>,
    Path(club_id): Path<u32>,
    Json(body): Json<CreateMember>,
) -> impl IntoResponse {
    let name = body.name.unwrap_or_default().trim().to_string();
    let email = body.email.unwrap_or_default().trim().to_string();
    if name.is_empty() {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "name is required"}))).into_response();
    }
    if email.is_empty() {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "email is required"}))).into_response();
    }

    let mut store = state.store.lock().unwrap();
    if !store.clubs.contains_key(&club_id) {
        return (StatusCode::NOT_FOUND, Json(json!({"error": "club not found"}))).into_response();
    }
    let id = store.next_member_id;
    store.next_member_id += 1;
    let member = Member { id, club_id, name, email };
    store.members.insert(id, member.clone());
    (StatusCode::CREATED, Json(member)).into_response()
}

#[derive(Deserialize)]
pub struct BulkMemberInput {
    pub name: Option<String>,
    pub email: Option<String>,
}

#[derive(Deserialize)]
pub struct BulkAddMembers {
    pub members: Vec<BulkMemberInput>,
}

pub async fn bulk_add_members(
    State(state): State<Arc<AppState>>,
    Path(club_id): Path<u32>,
    Json(body): Json<BulkAddMembers>,
) -> impl IntoResponse {
    if body.members.is_empty() {
        return (StatusCode::BAD_REQUEST, Json(json!({"error": "members must be a non-empty array"}))).into_response();
    }

    let mut store = state.store.lock().unwrap();
    let club = match store.clubs.get(&club_id) {
        Some(c) => c.clone(),
        None => return (StatusCode::NOT_FOUND, Json(json!({"error": "club not found"}))).into_response(),
    };

    let mut validated: Vec<(String, String)> = Vec::with_capacity(body.members.len());
    for m in &body.members {
        let name = m.name.clone().unwrap_or_default().trim().to_string();
        let email = m.email.clone().unwrap_or_default().trim().to_string();
        if name.is_empty() {
            return (StatusCode::BAD_REQUEST, Json(json!({"error": "name is required"}))).into_response();
        }
        if email.is_empty() {
            return (StatusCode::BAD_REQUEST, Json(json!({"error": "email is required"}))).into_response();
        }
        validated.push((name, email));
    }

    if let Some(max) = club.max_members {
        let current = store.member_count_for_club(club_id);
        if current + validated.len() as u32 > max {
            return (StatusCode::BAD_REQUEST, Json(json!({"error": "batch would exceed club max_members"}))).into_response();
        }
    }

    let mut created: Vec<Member> = Vec::with_capacity(validated.len());
    for (name, email) in validated {
        let id = store.next_member_id;
        store.next_member_id += 1;
        let member = Member { id, club_id, name, email };
        store.members.insert(id, member.clone());
        created.push(member);
    }
    (StatusCode::CREATED, Json(created)).into_response()
}

pub async fn list_members(
    State(state): State<Arc<AppState>>,
    Path(club_id): Path<u32>,
) -> impl IntoResponse {
    let store = state.store.lock().unwrap();
    if !store.clubs.contains_key(&club_id) {
        return (StatusCode::NOT_FOUND, Json(json!({"error": "club not found"}))).into_response();
    }
    let mut members: Vec<Member> = store
        .members
        .values()
        .filter(|m| m.club_id == club_id)
        .cloned()
        .collect();
    members.sort_by_key(|m| m.id);
    (StatusCode::OK, Json(members)).into_response()
}

